                            "publishTime":  "2026-01-18T01:53:24.483357719Z",
                            "flagContentUri":  "https://www.google.com/local/content/rap/report?postId=Ci9DQUlRQUNvZENodHljRjlvT2tvd1ZUUkhlVzV6V0ZoTlpFeHFaMUl4ZUZsbUxVRRAB\u0026d=17924085\u0026t=1",
                            "googleMapsUri":  "https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sCi9DQUlRQUNvZENodHljRjlvT2tvd1ZUUkhlVzV6V0ZoTlpFeHFaMUl4ZUZsbUxVRRAB!2m1!1s0x3442abbbf8243329:0xec3236fd72077e8f"
