                            "publishTime":  "2026-03-09T07:46:19.077181857Z",
                            "flagContentUri":  "https://www.google.com/local/content/rap/report?postId=Ci9DQUlRQUNvZENodHljRjlvT2t4UGVEQmplVlZtTTJFd2JIWldhakphUlZWT2VuYxAB\u0026d=17924085\u0026t=1",
                            "googleMapsUri":  "https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sCi9DQUlRQUNvZENodHljRjlvT2t4UGVEQmplVlZtTTJFd2JIWldhakphUlZWT2VuYxAB!2m1!1s0x3442ab2f7ab7e69d:0x4194d4c4c8519a24"
